test('imported tickets use configured deadlines and retain assignment and overdue filters', async () => {
  const clock = manualClock();
  await withService({ clock, dueTimes: true, dueHours: { urgent: 2 } }, async (api, service) => {
    const result = await api.post('/tickets/import', { tickets: [
      ticketBody({ priority: 'urgent' }), ticketBody({ priority: 'urgent' }),
    ] });
    assert.equal(result.status, 201);
    assert.equal(Date.parse(service.store.get('T-0001').due) - clock.now().getTime(), 2 * HOUR);
    await api.put('/tickets/T-0001/assignee', { assignee: 'Dana' });
    const due = service.store.get('T-0001').due;
    await api.patch('/tickets/T-0001', { priority: 'low' });
    clock.advance(2 * HOUR + 1);
    const page = await api.get('/tickets?overdue=true&assignee=Dana');
    assert.deepEqual(page.body.items.map(ticket => ticket.id), ['T-0001']);
    assert.equal(page.body.items[0].due, due);
    assert.equal(page.body.items[0].assignee, 'Dana');
  });
});
